_RESET = "\033[0m"
_LABELS = {"info": "[信息]", "warning": "[警告]", "critical": "[严重]", "debug": "[调试]"}

def _enable_vt100():
    if sys.platform == "win32":
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32
            kernel32.SetConsoleMode(kernel32.GetStdHandle(-11), 7)
        except Exception:
            pass

class Alerter:
    def __init__(self, config: AlertsConfig, store: StateStore, state: dict):
        self.config = config
        self.store = store
        self.state = state
        _enable_vt100()

